p = 'tests/services/member-service.test.ts'
s = open(p).read()
s = s.replace('''import * as memberService from "@/server/services/member-service";
''', '''import * as usageRepo from "@/server/repositories/usage-repository";
import * as memberService from "@/server/services/member-service";
import { registerUsageListeners } from "@/server/services/usage-service";
''')
assert s.rstrip().endswith('});')
s = s.rstrip()[:-3]  # drop final "});"
s += '''
  // A viewer is free; promoting one to a billable role takes a seat.
  it("refuses viewer -> billable when the plan has no seat left", async () => {
    // Free plan: 3 seats, all taken by owner, admin and member.
    const tenant = await createTenant("member-seat-full", "free");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    await expect(
      memberRepo.findMemberById(tenant.org.id, target.id),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  it("allows viewer -> billable while a seat is free", async () => {
    const tenant = await createTenant("member-seat-room", "starter");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    const updated = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
      role: "member",
    });
    expect(updated.role).toBe("member");
  });

  it("never applies the seat quota to other role changes", async () => {
    const tenant = await createTenant("member-seat-other", "free");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!admin || !member) throw new Error("fixture member missing");

    // billable -> billable on a full plan
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "admin",
      }),
    ).resolves.toMatchObject({ role: "admin" });

    // billable -> viewer on a full plan
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  it("counts a pending billable invitation when a viewer is promoted", async () => {
    const tenant = await createTenant("member-seat-pending", "starter");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    // Starter: 10 seats, 3 taken by members; 7 pending admins fill the plan.
    for (let i = 0; i < 7; i += 1) {
      await invitationRepo.insertInvitation(
        tenant.org.id,
        {
          orgId: tenant.org.id,
          email: `pending${i}@member-seat-pending.test`,
          role: "admin",
          expiresInDays: 14,
        },
        tenant.userIds.owner,
        `member-seat-pending-${i}`,
      );
    }

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);
